        body="""RadarGraph out{};if(range<1)return out;if(sectors.empty()){out.valid=true;return out;}const int h=static_cast<int>(sectors.size()),w=static_cast<int>(sectors.front().size());if(w==0)return out;for(const auto&r:sectors)if(static_cast<int>(r.size())!=w)return out;std::map<char,std::pair<int,int>>p;for(int r=0;r<h;++r)for(int c=0;c<w;++c){char x=sectors[r][c];if(x>='A'&&x<='Z'){if(!p.emplace(x,std::make_pair(r,c)).second)return RadarGraph{};}else if(x!='.'&&x!='#')return RadarGraph{};}for(auto [x,unused]:p){static_cast<void>(unused);out.beacons.push_back(x);}std::set<std::pair<char,char>>seen;for(auto [x,q]:p)for(int dr=-1;dr<=1;++dr)for(int dc=-1;dc<=1;++dc)if(dr!=0||dc!=0)for(int step=1;step<=range;++step){int r=q.first+dr*step,c=q.second+dc*step;if(r<0||r>=h||c<0||c>=w||sectors[r][c]=='#')break;char y=sectors[r][c];if(y>='A'&&y<='Z'){auto key=std::minmax(x,y);if(seen.insert(key).second)out.links.push_back({key.first,key.second,step});break;}}std::sort(out.links.begin(),out.links.end(),[](const RadarLink&a,const RadarLink&b){return std::tie(a.first,a.second)<std::tie(b.first,b.second);});for(char beacon:out.beacons){int nearest=0;for(const auto&link:out.links)if(link.first==beacon||link.second==beacon)nearest=nearest==0?link.distance:std::min(nearest,link.distance);out.nearest_distance.push_back({beacon,nearest});}out.valid=true;return out;""",
