        body="""HospitalForest out{};if(hospital.empty()){out.valid=true;return out;}const int h=static_cast<int>(hospital.size()),w=static_cast<int>(hospital.front().size());if(w==0)return out;for(const auto&r:hospital)if(static_cast<int>(r.size())!=w)return out;std::vector<int>id(static_cast<std::size_t>(h*w),-1);for(int r=0;r<h;++r)for(int c=0;c<w;++c)if(hospital[r][c]=='.')id[static_cast<std::size_t>(r*w+c)]=out.halls++;else if(hospital[r][c]!='#')return HospitalForest{};std::vector<std::vector<int>>adj(static_cast<std::size_t>(out.halls));const int dr[2]={0,1},dc[2]={1,0};for(int r=0;r<h;++r)for(int c=0;c<w;++c){int a=id[static_cast<std::size_t>(r*w+c)];if(a<0)continue;for(int d=0;d<2;++d){int nr=r+dr[d],nc=c+dc[d];if(nr<h&&nc<w){int b=id[static_cast<std::size_t>(nr*w+nc)];if(b>=0){adj[static_cast<std::size_t>(a)].push_back(b);adj[static_cast<std::size_t>(b)].push_back(a);}}}}std::vector<int>tin(static_cast<std::size_t>(out.halls),-1),low=tin,is_art(static_cast<std::size_t>(out.halls));std::vector<std::pair<int,int>>stack;std::vector<std::set<int>>members;int timer=0;std::function<void(int,int)>dfs=[&](int v,int parent){tin[static_cast<std::size_t>(v)]=low[static_cast<std::size_t>(v)]=timer++;int children=0;for(int to:adj[static_cast<std::size_t>(v)])if(to!=parent){if(tin[static_cast<std::size_t>(to)]<0){stack.push_back({v,to});++children;dfs(to,v);low[static_cast<std::size_t>(v)]=std::min(low[static_cast<std::size_t>(v)],low[static_cast<std::size_t>(to)]);if(low[static_cast<std::size_t>(to)]>=tin[static_cast<std::size_t>(v)]){if(parent>=0||children>1)is_art[static_cast<std::size_t>(v)]=1;std::set<int>block;while(!stack.empty()){auto edge=stack.back();stack.pop_back();block.insert(edge.first);block.insert(edge.second);if(edge==std::make_pair(v,to))break;}members.push_back(block);}}else if(tin[static_cast<std::size_t>(to)]<tin[static_cast<std::size_t>(v)]){stack.push_back({v,to});low[static_cast<std::size_t>(v)]=std::min(low[static_cast<std::size_t>(v)],tin[static_cast<std::size_t>(to)]);}}};for(int v=0;v<out.halls;++v)if(tin[static_cast<std::size_t>(v)]<0){if(adj[static_cast<std::size_t>(v)].empty())members.push_back({v});else dfs(v,-1);}for(int v=0;v<out.halls;++v)if(is_art[static_cast<std::size_t>(v)])out.articulations.push_back(v);out.blocks=static_cast<int>(members.size());for(int b=0;b<out.blocks;++b)for(int v:members[static_cast<std::size_t>(b)])if(is_art[static_cast<std::size_t>(v)])out.incidence.push_back({v,b});out.valid=true;return out;""",
